 perform public.post_fan_ticket_entry(owner,b,'credit',3,'fixture',b,extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.get_fan_ticket_balance(owner,a)=2 and public.get_fan_ticket_balance(owner,b)=3,'disabled release retains legacy creator balances');
