 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=300 and public.group_wallet_balance(owner,'ticket')=5,'legacy free balances project once without copying rows');
 perform pg_temp.wallet_assert(public.mobile_fan_economy_balance(owner,b,'fan_point')=300 and public.get_fan_ticket_balance(owner,a)=5,'legacy readers use same global free balance');
 perform pg_temp.wallet_assert(public.post_fan_ticket_entry(owner,a,'credit',2,'fixture',a,legacy_key,2)=prior||'{"replayed":true}'::jsonb,'old receipt replay preserves original creator and resulting balance');
 -- Hearts need a rewarded-ad session exactly like tickets (strategy doc 6.3-6.4).
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1)',owner,key),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=300 and public.group_wallet_balance(owner,'support_voucher')=0 and not exists(select 1 from public.group_wallet_receipts where app_user_id=owner and request_key=key),'a heart request without an ad session is refused (hearts are no longer purchasable) and changes nothing');
 ad:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
 perform public.report_owned_group_wallet_ad_session(owner,ad,'shown',1);perform pg_sleep(1.2);perform public.report_owned_group_wallet_ad_session(owner,ad,'granted',1);
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1,%L,2)',owner,key,ad),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=300 and public.group_wallet_balance(owner,'support_voucher')=0 and(select consumed_request_key is null and consumed_at is null from public.group_wallet_ad_sessions where id=ad)and not exists(select 1 from public.group_wallet_receipts where app_user_id=owner and request_key=key),'a heart request with a granted ad session is refused, keeps the session unspent and writes no receipt');
