 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1)',owner,extensions.gen_random_uuid()),'AD_SESSION_REQUIRED');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),extensions.gen_random_uuid()),'AD_SESSION_INVALID');
