 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_error(format('select public.report_owned_group_wallet_ad_session(%L,%L,''granted'',1)',owner,ad),'AD_SESSION_INVALID');
