 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 ad:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
