 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,1)',owner,extensions.gen_random_uuid(),ad),'AD_DAILY_LIMIT');
