 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'support_voucher')=0 and public.group_wallet_balance(owner,'fan_point')=200 and(select consumed_at is null from public.group_wallet_ad_sessions where id=ad),'a refused heart keeps balances and the ticket daily cap still applies');
