 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'support_voucher')=0 and public.group_wallet_balance(owner,'fan_point')=200 and(select consumed_at is null from public.group_wallet_ad_sessions where id=ad),'a heart request with an expired session is refused and keeps balances');
 source:=extensions.gen_random_uuid();
 insert into public.group_wallet_receipts values(owner,source,'exchange','{"policyVersion":"group-wallet-v1","target":"heart","units":1}'::jsonb,'{"requestKey":"x","target":"heart","units":1,"replayed":false}'::jsonb,clock_timestamp());
