 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,3)',owner,source,ad),'REQUEST_CONFLICT');
 perform public.post_fan_ticket_entry(owner,a,'debit',-3,'fixture_debit',extensions.gen_random_uuid(),extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3 and public.get_fan_ticket_balance(owner,b)=3,'legacy debit consumes same tickets as global exchange');
 perform pg_temp.wallet_error(format('select public.group_wallet_post(%L,''ticket'',-4,''group_capsule'',%L)',owner,extensions.gen_random_uuid()),'INSUFFICIENT_BALANCE');
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3,'failed debit does not spend');
