 perform public.check_in_owned_group_wallet(owner,key);perform public.check_in_owned_group_wallet(owner,extensions.gen_random_uuid());
 perform pg_temp.wallet_assert((select count(*)from public.group_wallet_attendance where app_user_id=owner and attendance_date=today)=1 and public.group_wallet_balance(owner,'fan_point')=290,'same date and key award exactly once');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(other,key)->>'status'='unknown','receipt ownership isolated');
 perform pg_temp.wallet_assert(not exists(select 1 from public.community_stamps where app_user_id=owner)and not exists(select 1 from public.fan_score_ledger where app_user_id=owner),'global points do not mint creator stamps or change XP');
