declare mk uuid:=extensions.gen_random_uuid();ledger_before bigint;points_before bigint;hearts_before bigint;stored jsonb;replayed jsonb;requests_before bigint;begin
  select count(*)into ledger_before from public.mobile_fan_economy_ledger where app_user_id=owner;requests_before:=(select count(*)from public.mobile_fan_economy_requests where app_user_id=owner);
  points_before:=public.group_wallet_balance(owner,'fan_point');hearts_before:=public.group_wallet_balance(owner,'support_voucher');
  perform pg_temp.wallet_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''group-wallet-a'',''support_voucher'',''fixture-v1'',1)',owner,mk),'POLICY_UNCONFIGURED');
  perform pg_temp.wallet_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''group-wallet-a'',''support_voucher'',''fixture-v1'',1000)',owner,extensions.gen_random_uuid()),'POLICY_UNCONFIGURED');
  perform pg_temp.wallet_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''group-wallet-a'',''free_draw'',''fixture-v1'',1)',owner,extensions.gen_random_uuid()),'POLICY_UNCONFIGURED');
  perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=points_before and public.group_wallet_balance(owner,'support_voucher')=hearts_before and(select count(*)from public.mobile_fan_economy_ledger where app_user_id=owner)=ledger_before and(select count(*)from public.mobile_fan_economy_requests where app_user_id=owner)=requests_before,'mobile exchange refuses new heart and ticket requests without an ad and leaves balances, ledger and receipts unchanged');
  stored:=jsonb_build_object('requestKey',mk,'celebrityId',a,'target','support_voucher','units',1,'pointsSpent',100,'pointLedgerId',extensions.gen_random_uuid(),'creditLedgerId',extensions.gen_random_uuid(),'policyVersion','fixture-v1','createdAt',clock_timestamp(),'replayed',false);
  insert into public.mobile_fan_economy_requests values(owner,mk,'exchange',jsonb_build_object('celebritySlug','group-wallet-a','target','support_voucher','policyVersion','fixture-v1','units',1),stored,clock_timestamp());
  replayed:=public.exchange_owned_mobile_fan_economy(owner,mk,'group-wallet-a','support_voucher','fixture-v1',1);
  perform pg_temp.wallet_assert(replayed=stored||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'fan_point')=points_before and public.group_wallet_balance(owner,'support_voucher')=hearts_before and(select count(*)from public.mobile_fan_economy_ledger where app_user_id=owner)=ledger_before,'mobile heart exchange committed before the closure still replays its stored result without new ledger rows');
